Ui.Script:
-- This fork's login screen keeps logging in, Credits and Cinematics: Quit, the stock
-- screen's Terms of Use, Community Site and Manage Account, and Turtle WoW's Reddit,
-- Discord, forum, database, armory and website buttons are hidden for good.
for _, name in ipairs({
    "AccountLoginExitButton", "AccountLoginTOSButton", "AccountLoginCommunityButton",
    "AccountLoginManageAccountButton", "AccountLoginTurtleReddit",
    "AccountLoginTurtleDiscord", "AccountLoginTurtleCommunityForum",
    "AccountLoginTurtleKnowledgeDatabase", "AccountLoginTurtleArmory",
    "AccountLoginTurtleWebsite",
}) do
    local button = getglobal(name);
    if ( button ) then
        button:Hide();
        button.Show = button.Hide;
    end
end
-- The stock Credits button stands on Terms of Use; it takes that place, as Turtle's does.
if ( AccountLoginTOSButton ) then
    AccountLoginCreditsButton:ClearAllPoints();
    AccountLoginCreditsButton:SetPoint("BOTTOM", "AccountLoginExitButton", "TOP", 0, 80);
end
